struct non_const_char_range {
  std::string_view str;

  template <std::ranges::range R>
  explicit non_const_char_range(R&& range)
      : str(std::ranges::data(range), std::ranges::size(range)) {}

  auto begin() { return str.begin(); }
  auto end() { return str.end(); }
};

TEST(ranges_test, std_views_transform_range) {
