  auto parts = line | std::views::split(',') |
               std::views::transform(
                   [](auto part) { return non_const_char_range(part); });
  EXPECT_EQ(fmt::format("{}", parts),
            "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]");
  EXPECT_EQ(fmt::format("{:::}", parts),
            "[[a], [b, -, c], [d, -, e], [f]]");
}

TEST(ranges_test, std_views_split_nested) {
  std::string line = "a,b-c,d-e,f";
  auto parts = line | std::views::split(',') |
               std::views::transform(std::views::split('-'));
  EXPECT_EQ(fmt::format("{}", parts),
            "[[['a']], [['b'], ['c']], [['d'], ['e']], [['f']]]");
  EXPECT_EQ(fmt::format("{::::}", parts),
            "[[[a]], [[b], [c]], [[d], [e]], [[f]]]");
}
